class Base {
    // Compiler adds hidden vptr (Virtual Pointer)
public:
    virtual void func1() {} // Vtable Index 0
    virtual void func2() {} // Vtable Index 1
};

class Derived : public Base {
public:
    // Overrides func1 entry in Derived vtable
    void func1() override {}
};

// Runtime Polymorphism via vptr lookup
// p->vptr points to Derived's vtable
Base* p = new Derived();
p->func1(); // Calls Derived::func1 (Index 0)
p->func2(); // Calls Base::func2 (Index 1)
delete p;

// Vtable: Array of function pointers for the class type.
// Vptr: Hidden member in object, pointing to the Vtable.
